add('showkontrol_edit_timeline_layer_copy','Append a layer using an existing named layer as template, or rename an existing layer in a new offline timeline/show copy. Inspect first and supply the SHA-256. Layer removal and reordering are unsupported. Validate the result in ShowKontrol.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),operation:z.enum(['append','rename']),layerName:z.string().min(1),newName:z.string().min(1)},editTimelineLayerCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_create_show_track_copy','Create an empty track in an offline show copy using an existing empty timeline template. The set list is unchanged. Track names use ASCII letters, digits, spaces, underscores or hyphens. Part names use content/NAME.sktl with ASCII letters, digits, underscores or hyphens in NAME. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),templateName:z.string(),trackName:z.string().regex(/^[A-Za-z0-9 _-]*[A-Za-z0-9_-][A-Za-z0-9 _-]*$/),partName:z.string().regex(/^content\/[A-Za-z0-9_-]+\.sktl$/)},createShowTrackCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
const mixedGraphSchema=z.object({nodes:z.array(z.discriminatedUnion('kind',[z.object({kind:z.literal('cue'),template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1)}),z.object({kind:z.literal('patch'),template:z.string(),templateSha256:z.string().length(64),templateFormat:z.enum(['skf','skshow']),nodeId:z.string().min(1)})])).min(1).max(50),wires:z.array(z.object({from:z.number().int().nonnegative(),to:z.number().int().nonnegative()})).max(100).default([])});
const layerOperationsSchema=z.array(z.object({operation:z.enum(['append','rename']),layerName:z.string().min(1),newName:z.string().min(1)}));
const graphDonorSchema=z.object({file:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1)});
const patchSettingSchema=z.union([z.object({nodeId:z.string().min(1),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),templateNodeId:z.string().min(1),key:z.string().min(1)}),z.object({nodeIndex:z.number().int().nonnegative(),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),templateNodeId:z.string().min(1),key:z.string().min(1)})]);
add('showkontrol_compose_show_copy','Create a track or use existingPartName to target an existing timeline, then add 1–100 cues, optional fixture-supported cue graphs, and an optional set-list entry in one new offline show copy. Use either existingPartName alone, or templateName, trackName and partName for a new track. Set entries are only supported for new tracks. Inspect the source and each donor first. A per-cue donor overrides the default; null leaves that cue without a graph. A mixedGraph overrides the default donor and cannot be combined with a per-cue donor. Mixed graph settings use nodeIndex; donor settings use nodeId. Optional audioClipEdits run in order after track selection and layer operations, before cues. Up to 100 edits select existing clips and attributes; new-track templates have no clips. Optional cueEdits apply up to 100 ordered field edits to existing cues before adding cues. New tracks contain no existing cues. Values and app acceptance are unverified. This does not author media. Destination filesystem must support hard links. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),templateName:z.string().optional(),trackName:z.string().regex(/^[A-Za-z0-9 _-]*[A-Za-z0-9_-][A-Za-z0-9 _-]*$/).optional(),partName:z.string().regex(/^content\/[A-Za-z0-9_-]+\.sktl$/).optional(),existingPartName:z.string().min(1).optional(),layerOperations:layerOperationsSchema.optional(),audioClipEdits:audioClipEditsSchema.optional(),cueEdits:composeCueEditsSchema.optional(),cues:z.array(z.object({layer:z.number().int().nonnegative(),startMs:z.number().nonnegative(),lengthMs:z.number().positive(),label:z.string().min(1),donor:graphDonorSchema.nullable().optional(),mixedGraph:mixedGraphSchema.optional(),settings:z.array(z.union([z.object({nodeId:z.string().min(1),key:z.string().min(1),value:z.string()}),z.object({nodeIndex:z.number().int().nonnegative(),key:z.string().min(1),value:z.string()})])).optional(),patchSettings:z.array(patchSettingSchema).optional()})).min(1).max(100),donor:graphDonorSchema.optional(),set:z.object({name:z.string(),setName:z.string().min(1),createIfMissing:z.boolean().optional()}).optional()},composeShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
const patchOperationsSchema=z.array(z.discriminatedUnion('kind',[z.object({kind:z.literal('setting'),nodeId:z.string().optional(),key:z.string(),value:z.string()}).strict(),z.object({kind:z.literal('graph'),operation:z.enum(['duplicate_node','remove_node','add_connection','remove_connection']),nodeId:z.string().optional(),newNodeId:z.string().optional(),connection:z.object({fromNode:z.string(),fromPin:z.number().int().nonnegative(),toNode:z.string(),toPin:z.number().int().nonnegative()}).strict().optional()}).strict(),z.object({kind:z.literal('copy_node'),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),nodeId:z.string(),newNodeId:z.string()}).strict()])).min(1).max(100);
const composeTrackSchema=z.object({templateName:z.string().optional(),trackName:z.string().regex(/^[A-Za-z0-9 _-]*[A-Za-z0-9_-][A-Za-z0-9 _-]*$/).optional(),partName:z.string().regex(/^content\/[A-Za-z0-9_-]+\.sktl$/).optional(),existingPartName:z.string().min(1).optional(),layerOperations:layerOperationsSchema.optional(),audioClipEdits:audioClipEditsSchema.optional(),cueEdits:composeCueEditsSchema.optional(),cues:z.array(z.object({layer:z.number().int().nonnegative(),startMs:z.number().nonnegative(),lengthMs:z.number().positive(),label:z.string().min(1),donor:graphDonorSchema.nullable().optional(),mixedGraph:mixedGraphSchema.optional(),settings:z.array(z.union([z.object({nodeId:z.string().min(1),key:z.string().min(1),value:z.string()}),z.object({nodeIndex:z.number().int().nonnegative(),key:z.string().min(1),value:z.string()})])).optional(),patchSettings:z.array(patchSettingSchema).optional()})).min(1).max(100),donor:graphDonorSchema.optional(),set:z.object({name:z.string(),setName:z.string().min(1),createIfMissing:z.boolean().optional()}).optional()});
add('showkontrol_compose_multi_track_show_copy','Compose cues on 1–20 new or existing tracks, optional fixture-supported graphs and set-list entries in one new offline show copy. Each track follows showkontrol_compose_show_copy. Optional patchOperations run first using showkontrol_edit_patch_batch_copy restrictions. Node removal checks the patch and supported .skf, .sktl, .sksc and .skls parts for ID text. The check can reject harmless text; other parts and external references are not checked. Inspect the source and donors first. This does not author media. Destination filesystem must support hard links. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),tracks:z.array(composeTrackSchema).min(1).max(20),patchOperations:patchOperationsSchema.optional()},composeMultiTrackShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_show_setlist','Inspect a version 2 set list part in an offline .skshow. Returns set names and track entries plus the source checksum.',{file:z.string(),name:z.string()},inspectShowSetlist,readOnly);
add('showkontrol_add_show_setlist_track_copy','Append an existing show track to a set in a new offline .skshow copy. Inspect the set list first and supply its source checksum. App acceptance of this edit is not yet verified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),setName:z.string().min(1),trackName:z.string().min(1)},addShowSetlistTrackCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_show_setlist_copy','Create a set, remove a track entry, or move a track entry in an offline show copy. Inspect first and use its SHA-256. Track indices are zero-based. Set removal and reordering are unsupported because the active-set reference is unverified. Validate the result in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),operation:z.enum(['create_set','remove_track','move_track']),setName:z.string().optional(),newSetName:z.string().optional(),index:z.number().int().nonnegative().optional(),toIndex:z.number().int().nonnegative().optional()},editShowSetlistCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_cue_graph','Inspect a cue graph in an offline .sktl or a named .sktl part of a .skshow. Returns graph nodes, connections and settings without changing the source.',{file:z.string(),format:z.enum(['sktl','skshow']),name:z.string().optional(),cueId:z.string()},inspectCueGraph,readOnly);
add('showkontrol_remove_cue_graph_copy','Remove the action graph from a cue in a new offline timeline or show copy. The cue remains. External references are not checked. Inspect first, supply the SHA-256, and validate the result in ShowKontrol.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1)},removeCueGraphCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_cue_graph_wire_copy','Add or remove a pin-0 connection within a cue graph in a new offline copy. Supports only fixture-observed groupin-to-trigger and trigger-to-action wires. Inspect first. Pin compatibility beyond these cases and ShowKontrol acceptance are not verified.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1),operation:z.enum(['add','remove']),fromNode:z.string().min(1),toNode:z.string().min(1)},editCueGraphWireCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_cue_graph_settings_show_copy','Change 1–100 existing cue graph settings in one new offline show copy. Inspect the source checksum first. Each setting selects a timeline, cue, node and key. The destination filesystem must support hard links. Values and app acceptance are not validated.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),settings:z.array(z.object({name:z.string().min(1),cueId:z.string().min(1),nodeId:z.string().min(1),key:z.string().min(1),value:z.string()})).min(1).max(100)},editCueGraphSettingsShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_cue_graph_setting_copy','Change an existing setting on a node in a cue graph in a new offline copy. Inspect the graph and source checksum first. Values and app acceptance are not validated; inspect the node type and verify in ShowKontrol.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1),nodeId:z.string().min(1),key:z.string().min(1),value:z.string()},editCueGraphSettingCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_add_cue_graph_setting_copy','Add a missing fixture-supported setting to a node in a cue graph in a new offline copy. Supports trigger.path and trigger.on on trigger nodes and action.category on action nodes. Inspect first. Values and ShowKontrol acceptance are not validated.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1),nodeId:z.string().min(1),key:z.string().min(1),value:z.string()},addCueGraphSettingCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_cue_graph_show_copy','Copy a fixture-supported cue graph to a graph-free cue in a new offline show copy. name selects the target timeline; sourceName selects the source timeline. To use another show, supply both template and its inspected templateSha256. Allocates fresh node IDs after scanning target XML parts. Supports groupin, trigger, and action nodes only. Rejects unsupported ID-like references. Router targets must match one destination patch router name. Check the result in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),sourceName:z.string().optional(),template:z.string().optional(),templateSha256:z.string().length(64).optional(),sourceCueId:z.string(),targetCueId:z.string()},copyCueGraphInShow,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_cue_graphs_show_copy','Copy 1–100 fixture-supported graphs into cues in one new offline show copy. Each item uses the same fields as showkontrol_copy_cue_graph_show_copy except source, destination and sha256. Destination filesystem must support hard links. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),copies:z.array(z.object({name:z.string(),sourceName:z.string().optional(),template:z.string().optional(),templateSha256:z.string().length(64).optional(),sourceCueId:z.string().min(1),targetCueId:z.string().min(1)})).min(1).max(100)},copyCueGraphsInShow,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_cue_graph_timeline_copy','Copy a fixture-supported cue graph from a standalone .sktl template into an empty cue in another .sktl copy. Inspect both files and supply both SHA-256 values. Node IDs are unique only within the target timeline; check the entire show for collisions before combining files. Supports groupin, trigger, and action nodes only. Rejects unsupported ID-like references and router targets. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),template:z.string(),templateSha256:z.string().length(64),sourceCueId:z.string().min(1),targetCueId:z.string().min(1)},copyCueGraphBetweenTimelines,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_cue_graph_node_show_copy','Copy one fixture-supported graph node from a cue in a template show into a cue graph in a new target show copy. Inspect both shows first. No wires are copied; internal ID-like references are rejected. Validate the result in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1)},copyCueGraphNodeShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_node_to_cue_show_copy','Copy an action or trigger node from an inspected offline patch into a cue graph in a new show copy. No wires are copied; internal ID-like references are rejected. Node behavior in a cue graph and app acceptance remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),nodeId:z.string().min(1)},copyPatchNodeToCueShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_setting_to_cue_show_copy','Copy one setting from an offline patch action or trigger node to a same-type cue graph node in a new show copy. Inspect both files first. Matching node types do not prove action-category compatibility; values, dependencies and ShowKontrol acceptance remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodeId:z.string().min(1),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),templateNodeId:z.string().min(1),key:z.string().min(1)},copyPatchSettingToCueShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_assemble_cue_graph_show_copy','Assemble 1–50 fixture-supported nodes and up to 100 pin-0 wires in a cue graph in a new offline show copy. Wire from/to are zero-based indices into nodes. A graph-free cue must be empty or whitespace-only. Inspect the source and each template first. Destination filesystem must support hard links. App acceptance and external dependencies remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodes:z.array(z.object({template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1)})).min(1).max(50),wires:z.array(z.object({from:z.number().int().nonnegative(),to:z.number().int().nonnegative()})).max(100).default([])},assembleCueGraphShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_assemble_mixed_cue_graph_show_copy','Assemble 1–50 nodes from cue or patch templates and up to 100 fixture-supported pin-0 wires into a new offline show copy. Wire from/to are zero-based indices into nodes. Inspect the source and each template first. Destination filesystem must support hard links. Node behavior in cue graphs, external dependencies and app acceptance remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodes:z.array(z.discriminatedUnion('kind',[z.object({kind:z.literal('cue'),template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1)}),z.object({kind:z.literal('patch'),template:z.string(),templateSha256:z.string().length(64),templateFormat:z.enum(['skf','skshow']),nodeId:z.string().min(1)})])).min(1).max(50),wires:z.array(z.object({from:z.number().int().nonnegative(),to:z.number().int().nonnegative()})).max(100).default([])},assembleMixedCueGraphShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_remove_cue_graph_node_copy','Remove an unreferenced cue graph node from a new offline timeline or show copy. Known ID references in supported parts are rejected; external systems and unrecognized parts are not checked. The check may reject harmless text. Inspect first and validate in ShowKontrol.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1),nodeId:z.string().min(1)},removeCueGraphNodeCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_patch','Inspect nodes, connections and existing settings in an offline version 2 patch (.skf) or .skshow wrapper.',{file:z.string(),format:z.enum(['skf','skshow'])},inspectPatch,readOnly);
add('showkontrol_edit_patch_setting_copy','Change one existing application or node setting in an offline patch copy. Inspect first and supply its SHA-256. Values are strings; accepted values and application compatibility are not validated. The destination must not exist.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),nodeId:z.string().optional().describe('Node ID; omit for an application setting'),key:z.string(),value:z.string()},editPatchSettingCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_patch_graph_copy','Duplicate or remove a node, or add or remove a connection in an offline patch copy. Inspect first. Node removal requires all its connections to be removed first. It checks the remaining patch and supported .skf, .sktl, .sksc and .skls show parts for ID text. The check can reject harmless text; other parts and external references are not checked. Duplicates retain settings, title and position. Pin and node compatibility is not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),operation:z.enum(['duplicate_node','remove_node','add_connection','remove_connection']),nodeId:z.string().optional(),newNodeId:z.string().optional(),connection:z.object({fromNode:z.string(),fromPin:z.number().int().nonnegative(),toNode:z.string(),toPin:z.number().int().nonnegative()}).optional()},editPatchGraphCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_patch_batch_copy','Apply 1–100 ordered setting, graph, and donor-node operations to an offline patch copy. Inspect all sources and supply their SHA-256 hashes. The destination must not exist. Removing a node deletes it from the offline copy; removal checks the remaining patch and supported .skf, .sktl, .sksc and .skls show parts for ID text. The check can reject harmless text; other parts and external references are not checked. Node copies retain internal references and do not copy connections or dependencies. Values, compatibility and ShowKontrol acceptance are not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),operations:patchOperationsSchema},editPatchBatchCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_node','Copy one existing node from an offline template patch into a new offline destination patch copy. Inspect both files first. Copies node XML only; no connections or dependencies. The copied title, position, settings and internal references remain unchanged. Compatibility is not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),nodeId:z.string(),newNodeId:z.string()},copyPatchNode,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_xml','Inspect an offline UTF-8 XML file and return its SHA-256 checksum and exact text. Do not use this to edit an active show.',{file:z.string()},inspectXml,readOnly);
add('showkontrol_edit_xml_copy','Apply exact unique text replacements to an offline XML file and write a new file. Requires the checksum from inspection. The source and all unmodified text are preserved. This validates XML syntax only, not ShowKontrol schema or compatibility.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),edits:z.array(z.object({find:z.string().min(1),replace:z.string()})).min(1)},editXmlCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_show','Read an offline .skshow wrapper manifest and verify part MD5 checksums.',{file:z.string()},inspectShow,readOnly);
add('showkontrol_inspect_show_media','Inventory literal media.map mappings, archive parts and timeline audio clips from an offline show; does not test playback or access external media.',{file:z.string()},inspectShowMedia,readOnly);
add('showkontrol_inspect_show_overview','Summarize an offline show from one consistent snapshot: parts, tracks, cues, set lists, and patch nodes. Fails on invalid checksums or unsupported native structures.',{file:z.string()},inspectShowOverview,readOnly);
add('showkontrol_validate_show','Check an offline show snapshot for part checksums, duplicate node IDs, graph connections and set-track references. Unsupported or invalid parts can make checks incomplete. This does not validate pin compatibility or prove that ShowKontrol will load or run the show.',{file:z.string()},validateShow,readOnly);
add('showkontrol_read_show_part','Read a UTF-8 part from an offline .skshow file after verifying its MD5.',{file:z.string(),name:z.string()},readShowPart,readOnly);
add('showkontrol_read_show_part_page','Read a bounded page of a UTF-8 show part. Offsets count UTF-16 code units; use nextOffset for the next page and pass the returned sha256 to detect changes between pages. A page never splits a Unicode character.',{file:z.string(),name:z.string(),offset:z.number().int().nonnegative().default(0),limit:z.number().int().min(2).max(32768).default(16384),sha256:z.string().length(64).optional()},readShowPartPage,readOnly);
add('showkontrol_edit_show_part_copy','Edit one XML part of an offline .skshow file. Verify all part checksums and source SHA-256, update the edited part MD5, and write a new file. XML validity does not prove ShowKontrol compatibility.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),edits:z.array(z.object({find:z.string().min(1),replace:z.string()})).min(1)},editShowPart,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
